package cn.local.rainreminder;
import android.app.*;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.widget.*;import org.json.*;import java.time.*;import java.util.*;import java.util.function.*;

final class WeekTable {
 static final int[] COLORS={0xFFB9DAF4,0xFFC9E5C7,0xFFF9D5A7,0xFFE0CCF1,0xFFF3C3CE,0xFFAFE1DC,0xFFDDDFA8,0xFFC4D1F3};
 static final int[] START={480,535,600,655,870,925,990,1045,1140,1190,1240,1310},END={525,580,645,700,915,970,1035,1090,1190,1235,1285,1355};
 static int color(JSONObject e){return e.optInt("color",COLORS[Math.floorMod(e.optString("title").hashCode(),COLORS.length)]);}
 static final class Item {JSONObject event;long start,end;int day;Item(JSONObject e,long s,long t,int d){event=e;start=s;end=t;day=d;}}
 static java.util.List<Item> occurrences(JSONArray events,LocalDate monday){java.util.List<Item> out=new ArrayList<>();ZoneId zone=ZoneId.systemDefault();for(int n=0;n<events.length();n++){JSONObject e=events.optJSONObject(n);if(e==null)continue;long base=e.optLong("start"),duration=e.optLong("end")-base;if(duration<=0)continue;LocalDate date=Instant.ofEpochMilli(base).atZone(zone).toLocalDate();int repeat=e.optInt("repeatDays");for(int day=0;day<7;day++){LocalDate at=monday.plusDays(day);long diff=java.time.temporal.ChronoUnit.DAYS.between(date,at);if(diff<0||(repeat==0?diff!=0:diff%repeat!=0))continue;long start=at.atTime(Instant.ofEpochMilli(base).atZone(zone).toLocalTime()).atZone(zone).toInstant().toEpochMilli();if(repeat>0&&start>e.optLong("until"))continue;out.add(new Item(e,start,start+duration,day));}}out.sort((a,b)->Long.compare(a.start,b.start));return out;}
 static float position(long time){return position(time,ImportActivity.parseTimes(ImportActivity.TIMES));}
 static float position(long time,java.util.List<LocalTime[]> periods){LocalTime t=Instant.ofEpochMilli(time).atZone(ZoneId.systemDefault()).toLocalTime();float m=t.getHour()*60+t.getMinute();for(int i=0;i<periods.size();i++){int from=periods.get(i)[0].getHour()*60+periods.get(i)[0].getMinute(),to=periods.get(i)[1].getHour()*60+periods.get(i)[1].getMinute();if(m<from)return i;if(m<=to)return i+(m-from)/(to-from);}return periods.size();}
 static String clock(int m){return String.format(java.util.Locale.CHINA,"%02d:%02d",m/60,m%60);}
 static int columns(Activity a){return Agenda.prefs(a).getBoolean("showWeekend",true)?7:5;}
 static FrameLayout headers(Activity a,LocalDate monday){FrameLayout header=new FrameLayout(a);header.setBackgroundColor(0xF5F7F8FA);header.setLayoutParams(new LinearLayout.LayoutParams(-1,Ui.dp(a,46)));header.post(()->{int axis=Ui.dp(a,32),count=columns(a);float col=(header.getWidth()-axis)/(float)count;TextView month=Ui.text(a,monday.getMonthValue()+"月",10);month.setTextColor(Ui.MUTED);month.setGravity(Gravity.CENTER);header.addView(month,new FrameLayout.LayoutParams(axis,-1));for(int day=0;day<count;day++){LocalDate date=monday.plusDays(day);LinearLayout box=Ui.column(a);box.setGravity(Gravity.CENTER);FrameLayout.LayoutParams hp=new FrameLayout.LayoutParams(Math.round(col),-1);hp.leftMargin=axis+Math.round(day*col);header.addView(box,hp);TextView name=Ui.text(a,new String[]{"一","二","三","四","五","六","日"}[day],13);name.setTypeface(Ui.strong(a));name.setPadding(0,0,0,Ui.dp(a,2));TextView number=Ui.text(a,String.format(Locale.CHINA,"%02d-%02d",date.getMonthValue(),date.getDayOfMonth()),9);number.setPadding(0,0,0,0);number.setTextColor(Ui.MUTED);if(date.equals(LocalDate.now())){box.setBackground(Ui.bg(a,0xFFDDEDE7));name.setTextColor(Ui.GREEN);number.setTextColor(Ui.GREEN);}box.addView(name);box.addView(number);}});return header;}
 static void render(Activity a,LinearLayout parent,LocalDate monday,Consumer<JSONObject> edit,BiConsumer<LocalDate,Integer> add){parent.addView(headers(a,monday));renderBody(a,parent,monday,edit,add);}
 static void renderBody(Activity a,LinearLayout parent,LocalDate monday,Consumer<JSONObject> edit,BiConsumer<LocalDate,Integer> add){renderBody(a,parent,monday,edit,add,edit,null);}
 static void renderBody(Activity a,LinearLayout parent,LocalDate monday,Consumer<JSONObject> edit,BiConsumer<LocalDate,Integer> add,Consumer<JSONObject> longPress,Set<String> selected){
  java.util.List<LocalTime[]> periods=ImportActivity.parseTimes(ImportActivity.periodTimes(a));int count=periods.size(),columns=columns(a);
  int row=Ui.dp(a,Agenda.prefs(a).getInt("rowHeight",46)),font=Agenda.prefs(a).getInt("gridFont",10),axis=Ui.dp(a,32);float alpha=Agenda.prefs(a).getInt("cardOpacity",94)/100f;
  FrameLayout grid=new FrameLayout(a);grid.setClipChildren(true);parent.addView(grid,new LinearLayout.LayoutParams(-1,row*count));grid.setBackgroundColor(0xFFFAFAFC);java.io.File file=new java.io.File(a.getFilesDir(),"timetable-background.jpg");if(file.exists()){Bitmap bitmap=BitmapFactory.decodeFile(file.getPath());if(bitmap!=null){BitmapDrawable image=new BitmapDrawable(a.getResources(),bitmap);image.setGravity(Gravity.FILL);grid.setBackground(image);}}
  grid.post(()->{int width=grid.getWidth();float col=(width-axis)/(float)columns;
   View veil=new View(a);veil.setBackgroundColor(Color.argb(Agenda.prefs(a).getInt("backgroundVeil",40)*255/100,255,255,255));grid.addView(veil,new FrameLayout.LayoutParams(-1,-1));
   for(int day=0;day<columns;day++){LocalDate date=monday.plusDays(day);if(date.equals(LocalDate.now())){View band=new View(a);band.setBackgroundColor(0x10527C69);FrameLayout.LayoutParams bp=new FrameLayout.LayoutParams(Math.round(col),-1);bp.leftMargin=axis+Math.round(day*col);grid.addView(band,bp);}for(int p=0;p<count;p++){final int period=p;View blank=new View(a);GradientDrawable border=new GradientDrawable();border.setColor(0x00FFFFFF);border.setStroke(1,0x18A0A5B1);blank.setBackground(border);blank.setContentDescription(date+" 第"+(p+1)+"节，长按添加");blank.setOnLongClickListener(v->{if(selected==null)add.accept(date,period);return true;});FrameLayout.LayoutParams bp=new FrameLayout.LayoutParams(Math.round(col),row);bp.leftMargin=axis+Math.round(day*col);bp.topMargin=p*row;grid.addView(blank,bp);}}
   for(int p=0;p<count;p++){LinearLayout labels=Ui.column(a);labels.setGravity(Gravity.CENTER);TextView number=Ui.text(a,String.valueOf(p+1),12);number.setTypeface(Ui.strong(a));number.setGravity(Gravity.CENTER);number.setPadding(0,0,0,Ui.dp(a,2));labels.addView(number);TextView time=Ui.text(a,periods.get(p)[0]+"\n"+periods.get(p)[1],8);time.setLineSpacing(0,1);time.setGravity(Gravity.CENTER);time.setPadding(0,0,0,0);time.setTextColor(Ui.MUTED);labels.addView(time);FrameLayout.LayoutParams lp=new FrameLayout.LayoutParams(axis,row);lp.topMargin=p*row;grid.addView(labels,lp);}
   java.util.List<Item> items=occurrences(Agenda.all(a),monday);for(Item item:items){if(item.day>=columns)continue;float top=position(item.start,periods),bottom=Math.max(top+.55f,position(item.end,periods));int peers=1,index=0;for(Item other:items)if(other!=item&&other.day==item.day&&other.start<item.end&&other.end>item.start){peers++;if(other.start<item.start||other.start==item.start&&other.event.optString("id").compareTo(item.event.optString("id"))<0)index++;}float cell=col/peers;boolean checked=selected!=null&&selected.contains(item.event.optString("id"));String title=(selected!=null&&item.event.optBoolean("course")?(checked?"✓ ":"○ "):"")+item.event.optString("title"),place=item.event.optString("place");android.text.SpannableString content=new android.text.SpannableString(title+(place.isEmpty()?"":"\n@"+place));content.setSpan(new android.text.style.StyleSpan(Typeface.BOLD),0,title.length(),0);if(content.length()>title.length())content.setSpan(new android.text.style.RelativeSizeSpan(.88f),title.length(),content.length(),0);TextView block=Ui.text(a,"",font);block.setText(content);block.setLineSpacing(0,1.03f);block.setPadding(Ui.dp(a,3),Ui.dp(a,4),Ui.dp(a,2),Ui.dp(a,2));block.setGravity(Gravity.TOP|Gravity.LEFT);int color=color(item.event);GradientDrawable bg=new GradientDrawable();bg.setColor(Color.argb((int)(255*alpha),Color.red(color),Color.green(color),Color.blue(color)));bg.setCornerRadius(Ui.dp(a,5));if(checked)bg.setStroke(Ui.dp(a,2),Ui.GREEN);block.setBackground(bg);block.setAlpha(item.event.optBoolean("enabled",true)?(item.end<System.currentTimeMillis()?.70f:1):.45f);block.setContentDescription(item.event.optString("title")+"，"+item.event.optString("place")+(selected==null?"，点击修改，长按多选":checked?"，已选中，点击取消选择":"，未选中，点击选择"));block.setTag("course:"+item.event.optString("id"));block.setOnClickListener(v->edit.accept(item.event));block.setOnLongClickListener(v->{longPress.accept(item.event);return true;});FrameLayout.LayoutParams bp=new FrameLayout.LayoutParams(Math.max(1,Math.round(cell)-Ui.dp(a,2)),Math.max(Ui.dp(a,24),(int)((bottom-top)*row)-Ui.dp(a,2)));bp.leftMargin=axis+Math.round(col*item.day+cell*index)+Ui.dp(a,1);bp.topMargin=(int)(top*row)+Ui.dp(a,1);grid.addView(block,bp);}
   int today=(int)java.time.temporal.ChronoUnit.DAYS.between(monday,LocalDate.now());LocalTime now=LocalTime.now();if(today>=0&&today<columns&&!now.isBefore(periods.get(0)[0])&&!now.isAfter(periods.get(count-1)[1])){View line=new View(a);line.setBackgroundColor(Ui.GREEN);line.setContentDescription("当前时间 "+now.withSecond(0).withNano(0));FrameLayout.LayoutParams lp=new FrameLayout.LayoutParams(Math.round(col),Ui.dp(a,2));lp.leftMargin=axis+Math.round(today*col);lp.topMargin=(int)(position(System.currentTimeMillis(),periods)*row);grid.addView(line,lp);}
  });
 }
}
